import {MOTOR_CLUB,MOTOR_SPOTS} from './motor-catalog.mjs?v=37';
import {CARS} from './driving.mjs?v=37';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createMotorUI(api){
 let pending=null,last=0,busy=false;const hud=document.createElement('section');hud.className='motor-hud hidden';hud.setAttribute('aria-label','Motor Club controls');hud.innerHTML='<div><small>RAE’S MOTOR CLUB</small><strong>Your crew. Your rides.</strong><span id="motorCount">Eight display bays · everyone welcome</span></div><nav><button data-motor-walk="style">PARTS COUNTER</button><button data-motor-walk="jobs">CREW JOBS</button><button data-motor-walk="chat">LOUNGE</button><button id="motorPhoto">CREW PHOTO</button><button id="motorExit">LEAVE CLUB</button></nav><button id="motorInteract">WALK TO A STATION</button>';document.body.append(hud);
 const entrance=document.createElement('button');entrance.id='motorEntrance';entrance.className='motor-entrance hidden';entrance.textContent='E · ENTER MOTOR CLUB';entrance.onclick=api.enter;document.body.append(entrance);
 hud.querySelectorAll('[data-motor-walk]').forEach(b=>b.onclick=()=>{pending=b.dataset.motorWalk;api.scene().walkTo(pending);});document.getElementById('motorPhoto').onclick=api.photo;document.getElementById('motorExit').onclick=api.exit;document.getElementById('motorInteract').onclick=()=>interact();
 async function interact(id){if(busy)return;const s=api.scene(),p=id?MOTOR_SPOTS.find(p=>p.id===id):s?.nearest();pending=null;if(!s)return;
  if(s.seated&&!id){await api.seat(null);s.sit(null);return;}if(!p)return;
  if(p.id==='exit'){api.exit();return;}if(p.id==='style'){api.customize();return;}if(p.id==='jobs'){api.jobs();return;}if(p.id==='chat'){api.chat();return;}
  if(p.id.startsWith('seat-')){busy=true;try{await api.sync();await api.seat(p.id);s.sit(p.id);}catch(e){api.notify(e.message);}finally{busy=false;}return;}
  const owner=s.inspect(p.id);if(!owner){api.notify('This bay is open. Bring a friend.');return;}const cfg=CARS[owner.carId]||CARS.van,style=owner.carStyle||{};api.pause();api.modal('<div class="motor-inspect"><button class="modal-close" data-close aria-label="Close vehicle details">×</button><small>MOTOR CLUB / '+esc(owner.name)+'’S RIDE</small><h2 id="dialogTitle">'+esc(cfg.name)+'</h2><img class="motor-ride-image" src="'+api.thumbnail(owner.carId,style)+'" alt="'+esc(owner.name)+'’s '+esc(cfg.name)+'"><p>'+esc(cfg.description)+'</p><div class="motor-specs"><span><b>'+Math.round(cfg.speed*4.6)+'</b> KM/H</span><span><b>'+cfg.seats+'</b> SEATS</span><span><b>'+cfg.health+'</b> INTEGRITY</span></div><dl><dt>Plate</dt><dd>'+esc(style.plate||'GETAWAY')+'</dd><dt>Paint</dt><dd><i style="background:'+(/^#[0-9a-f]{6}$/i.test(style.paint)?style.paint:'#efba56')+'"></i> '+(style.paint?'Custom finish':'Original finish')+'</dd><dt>Body kit</dt><dd>'+esc(style.bodyKit||'Factory')+'</dd><dt>Wheels</dt><dd>'+(style.wheelColor?'Custom finish':'Factory')+'</dd></dl>'+(owner.id===api.me()?'<button id="motorCustomizeRide">CUSTOMIZE MY RIDE</button>':'<p>Meet the owner in the lounge and chat about their build.</p>')+'<button data-close>BACK TO THE MEET</button></div>',true);const button=document.getElementById('motorCustomizeRide');if(button)button.onclick=api.customize;
 }
 function update(){const state=api.state(),inside=state.mode==='motor';document.body.classList.toggle('in-motor-club',inside);const near=['driving','walking'].includes(state.mode)&&Math.hypot(state.x-MOTOR_CLUB.x,state.z-MOTOR_CLUB.z)<MOTOR_CLUB.radius&&Math.abs(state.speed||0)<2;entrance.classList.toggle('hidden',!near||state.paused);hud.classList.toggle('hidden',!inside||state.paused||api.photoActive());if(!inside){pending=null;return;}const scene=api.scene(),n=scene.nearest();document.getElementById('motorInteract').disabled=busy||!n&&!scene.seated;document.getElementById('motorInteract').textContent=busy?'ONE SECOND…':scene.seated?'E · STAND UP':n?'E · '+n.label:'WALK TO A CAR OR STATION';if(pending&&!state.paused){const p=MOTOR_SPOTS.find(s=>s.id===pending);if(p&&Math.hypot(scene.avatar.position.x-p.x,scene.avatar.position.z-p.z)<.4)void interact(p.id);}
  if(Date.now()-last>400){last=Date.now();const list=api.members();scene.syncCars(list);document.getElementById('motorCount').textContent=api.room()?list.length+' DRIVER'+(list.length===1?'':'S')+' · NEIGHBORHOOD '+api.room()+' · '+Math.min(list.length,8)+'/8 DISPLAY BAYS':'OFFLINE · OPEN ONLINE TO REJOIN';}
 }
 return {update,interact};
}
